WITH filtered_orders AS (SELECT * FROM orders WHERE status IN ('RETURNED', 'PENDING') OR shipping_fee <= 28), status_summary AS (SELECT status, DATE_FORMAT(order_date, 'yyyy-MM') AS order_month, COUNT(*) AS order_count, SUM(CASE WHEN channel = 'store' THEN 1 ELSE 0 END) AS store_count FROM filtered_orders GROUP BY status, DATE_FORMAT(order_date, 'yyyy-MM')) SELECT * FROM status_summary WHERE order_count < 6 ORDER BY 2, order_count DESC, status LIMIT 20;
